import {GEAR} from './expedition-data.mjs';import {equipmentStats} from './expedition-equipment-view.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const routeLabel={foundry:'准备锈潮铸库',foundrywatch:'准备封库守望',chapter:'准备沉钟章节',harbor:'准备盐风港'};
export function soloStoryView({id,progress:p,endings,gold,title,label,intro,claimAttribute,followup}){
 const ending=p.ending&&endings[p.ending];
 return `<section class="guild-panel solo-story ${id}-story" data-guild-pane="journey" data-story-book="${id}"><p class="eyebrow">单人旅程 / ${label}</p><h2>${title}</h2><p>${intro}</p><p class="story-progress" role="status">旅程 ${p.completed}/3 · ${esc(p.reason)}</p><div class="story-steps">${p.steps.map((step,i)=>`<article class="story-step" data-story-step="${step.id}"><p class="eyebrow">第${i+1}段 · ${step.done?'已完成':'尚未完成'}</p><h3>${step.title}</h3><p>${esc(step.done?step.after:step.before)}</p><p><b>交接条件：</b>${step.condition}</p><button data-journey-prepare="${step.route}">${routeLabel[step.route]} →</button></article>`).join('')}</div>${ending?`<article class="story-ending" data-story-ending="${p.ending}"><p class="eyebrow">旅程结局 / 已记录</p><h3>${ending.name}</h3><p>${ending.text}</p><p>${gold}金币与${GEAR[ending.gear].name}已作为一次旅程奖励入库；之后通关仍按路线正常结算。</p><button data-guild-tab="equipment">去仓库分配装备 →</button>${followup?`<p>${esc(followup.text)}</p><button data-journey-prepare="${followup.route}">${esc(followup.label)} →</button>`:''}</article>`:`<h3>旅程之后，留下什么？</h3><p>可先阅读三个结局。完成三段条件后，选择一次交付：获得${gold}金币与该结局指定的一件装备，结局随公会备份保存。装备入仓后再分配，不额外发经验。</p><div class="story-endings">${Object.entries(endings).map(([key,e])=>`<article class="story-ending" data-story-choice="${key}"><h3>${e.name}</h3><p>${e.text}</p><p><b>${GEAR[e.gear].name} + ${gold}金币</b></p><small>${esc(equipmentStats(e.gear))}</small><button ${claimAttribute}="${key}" ${p.canClaim?'':'disabled'}>选择此结局并领取 · ${GEAR[e.gear].name}</button></article>`).join('')}</div>`}<p class="muted">结局记录用于这段单人故事与定向装备选择。正常远征奖励另算，实验、试演与历史重演不完成旅程，也不发放旅程奖励。路线顺序仍可自由选择，已有成果直接计入。</p></section>`;
}
